(function() {
    'use strict';

    class ClauseWorkAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'ClauseWork: Contract Negotiation';
            this.version = '1.0.0';
            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    descriptionKey: 'round1_desc',
                    optimalFocus: 'territorial',
                    baseValue: 600000,
                    baseClauses: 5,
                    hasEvent: false
                },
                {
                    titleKey: 'round2_title',
                    descriptionKey: 'round2_desc',
                    optimalFocus: 'commercial',
                    baseValue: 900000,
                    baseClauses: 6,
                    hasEvent: false
                },
                {
                    titleKey: 'round3_title',
                    descriptionKey: 'round3_desc',
                    optimalFocus: 'ip_liability',
                    baseValue: 700000,
                    baseClauses: 5,
                    hasEvent: true
                },
                {
                    titleKey: 'round4_title',
                    descriptionKey: 'round4_desc',
                    optimalFocus: 'governance',
                    baseValue: 500000,
                    baseClauses: 4,
                    hasEvent: false
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    dealValue: 0,
                    clausesResolved: 0,
                    counterpartyTrust: 70,
                    bargainingPower: 60,
                    dealSigned: false,
                    walkedAway: false,
                    dealValueHistory: [],
                    trustHistory: [],
                    powerHistory: [],
                    clausesHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    stance: 'balanced',
                    focus: 'commercial',
                    concession: 40,
                    infoStrategy: 'selective',
                    signing: 'sign'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var stanceInput = document.getElementById('stanceInput');
            if (stanceInput) decisions.stance = stanceInput.value;

            var focusInput = document.getElementById('focusInput');
            if (focusInput) decisions.focus = focusInput.value;

            var concessionInput = document.getElementById('concessionInput');
            if (concessionInput) decisions.concession = parseInt(concessionInput.value);

            var infoInput = document.getElementById('infoInput');
            if (infoInput) decisions.infoStrategy = infoInput.value;

            var signingInput = document.getElementById('signingInput');
            if (signingInput && document.getElementById('signingGroup').style.display !== 'none') {
                decisions.signing = signingInput.value;
            } else {
                decisions.signing = 'pending';
            }

            if (isNaN(decisions.concession) || decisions.concession < 0 || decisions.concession > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('concession_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var value = round.baseValue;
            var clausesGained = round.baseClauses;
            var trustChange = 0;
            var powerChange = 0;

            if (d.stance === 'aggressive') {
                value *= 1.3;
                trustChange -= 8;
                powerChange += 5;
                if (ds.counterpartyTrust < 40) {
                    clausesGained -= 2;
                    value *= 0.7;
                }
            } else if (d.stance === 'cooperative') {
                value *= 0.7;
                trustChange += 6;
                powerChange -= 3;
                clausesGained += 1;
            } else {
                trustChange -= 2;
                powerChange += 1;
            }

            if (d.focus === round.optimalFocus) {
                clausesGained += 2;
                value *= 1.15;
            } else {
                clausesGained -= 1;
            }

            if (d.concession <= 20) {
                value *= 1.2;
                trustChange -= 8;
                clausesGained -= 1;
            } else if (d.concession <= 50) {
                value *= 1.05;
            } else if (d.concession <= 80) {
                value *= 0.9;
                trustChange += 5;
                clausesGained += 1;
            } else {
                value *= 0.75;
                trustChange += 10;
                clausesGained += 2;
            }

            if (d.infoStrategy === 'reveal') {
                trustChange += 5;
                powerChange -= 5;
                clausesGained += 1;
            } else if (d.infoStrategy === 'withhold') {
                trustChange -= 5;
                powerChange += 8;
            }

            if (round.hasEvent) {
                powerChange -= 15;
                value *= 0.85;
            }

            var signingOutcome = 'in_progress';
            if (state.currentPeriod >= 4) {
                if (d.signing === 'walk') {
                    ds.walkedAway = true;
                    value = 0;
                    clausesGained = 0;
                    signingOutcome = 'walked_away';
                } else if (d.signing === 'continue') {
                    var luck = Math.random();
                    if (luck < 0.4) {
                        value *= 1.2;
                        signingOutcome = 'pushed_success';
                    } else {
                        value *= 0.5;
                        trustChange -= 10;
                        signingOutcome = 'pushed_backfired';
                    }
                } else {
                    ds.dealSigned = true;
                    signingOutcome = 'signed';
                }
            }

            value = Math.round(value);
            clausesGained = Math.max(0, Math.min(clausesGained, 20 - ds.clausesResolved));

            ds.dealValue += value;
            ds.clausesResolved += clausesGained;
            ds.counterpartyTrust = Math.max(0, Math.min(100, ds.counterpartyTrust + trustChange));
            ds.bargainingPower = Math.max(0, Math.min(100, ds.bargainingPower + powerChange));

            ds.dealValueHistory.push(ds.dealValue);
            ds.trustHistory.push(ds.counterpartyTrust);
            ds.powerHistory.push(ds.bargainingPower);
            ds.clausesHistory.push(ds.clausesResolved);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            return {
                period: state.currentPeriod,
                roundValue: value,
                clausesGained: clausesGained,
                trustChange: trustChange,
                powerChange: powerChange,
                totalDealValue: ds.dealValue,
                clausesResolved: ds.clausesResolved,
                trust: ds.counterpartyTrust,
                power: ds.bargainingPower,
                signingOutcome: signingOutcome
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('dealValueDisplay', 'domainState.dealValue',
                (v) => '€' + Math.round(v).toLocaleString());
            uiManager.bind('clausesDisplay', 'domainState.clausesResolved',
                (v) => v + ' / 20');
            uiManager.bind('trustDisplay', 'domainState.counterpartyTrust',
                (v) => Math.round(v) + '%');
            uiManager.bind('powerDisplay', 'domainState.bargainingPower',
                (v) => Math.round(v) + '%');
        }

        getChartConfig() {
            return {
                negotiationChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Deal Value (€K)',
                                data: [],
                                borderColor: '#2c3e50',
                                backgroundColor: 'rgba(44,62,80,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Counterparty Trust (%)',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            },
                            {
                                label: 'Bargaining Power (%)',
                                data: [],
                                borderColor: '#e67e22',
                                backgroundColor: 'rgba(230,126,34,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Negotiation Progress' }
                        },
                        scales: {
                            y: {
                                type: 'linear',
                                display: true,
                                position: 'left',
                                title: { display: true, text: 'Deal Value (€K)' },
                                beginAtZero: true
                            },
                            y1: {
                                type: 'linear',
                                display: true,
                                position: 'right',
                                title: { display: true, text: 'Percentage' },
                                min: 0,
                                max: 100,
                                grid: { drawOnChartArea: false }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.dealValueHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                negotiationChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.dealValueHistory.map(function(v) { return Math.round(v / 1000); }) },
                        { data: state.domainState.trustHistory },
                        { data: state.domainState.powerHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var totalValue = lastResult.totalDealValue || 0;
            var clauses = lastResult.clausesResolved || 0;
            var trust = lastResult.trust || 0;
            var signed = lastResult.signingOutcome === 'signed';
            var walked = lastResult.signingOutcome === 'walked_away';
            var pushSuccess = lastResult.signingOutcome === 'pushed_success';

            var score = 0;
            score += Math.min(35, Math.round(totalValue / 75000));
            score += Math.round((clauses / 20) * 30);
            score += Math.round((trust / 100) * 20);
            if (signed && trust >= 50) score += 15;
            else if (signed || pushSuccess) score += 8;
            else if (walked) score += 3;

            score = Math.min(100, score);

            var performance = 'Novice Negotiator';
            if (score >= 85) performance = 'Master Negotiator';
            else if (score >= 70) performance = 'Skilled Negotiator';
            else if (score >= 50) performance = 'Competent Negotiator';
            else if (score >= 30) performance = 'Developing Negotiator';

            var insights = [];
            if (totalValue > 2200000) {
                insights.push('Strong value capture with effective commercial positioning across all rounds.');
            } else if (totalValue > 1500000) {
                insights.push('Moderate deal value captured. More assertive commercial terms could improve outcomes.');
            } else {
                insights.push('Low deal value. Balancing assertiveness with concessions is key to capturing value.');
            }

            if (clauses >= 16) {
                insights.push('Excellent clause coverage for a comprehensive and enforceable term sheet.');
            } else if (clauses >= 10) {
                insights.push('Several clauses remain unresolved. Real deals require completeness to avoid future disputes.');
            } else {
                insights.push('Many clauses unresolved. Aligning focus area with the round theme resolves more clauses.');
            }

            if (trust >= 60) {
                insights.push('High counterparty trust supports long-term deal stability and reduces renegotiation risk.');
            } else if (trust >= 35) {
                insights.push('Moderate trust level. Consider more cooperative moves to strengthen the relationship.');
            } else {
                insights.push('Critically low trust risks post-signing disputes. Balance assertiveness with relationship building.');
            }

            if (walked) {
                insights.push('Walking away can be strategic, but only when your BATNA is truly better than the deal on the table.');
            }

            return {
                totalDealValue: totalValue,
                clausesResolved: clauses,
                counterpartyTrust: trust,
                dealSigned: signed,
                score: score,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.signingOutcome === 'pushed_backfired') return window.mySimulation.t('hint_push_failed');
            if (state.domainState.counterpartyTrust < 25) return window.mySimulation.t('hint_trust_critical');
            if (results.trustChange <= -8) return window.mySimulation.t('hint_trust_drop');
            if (results.clausesGained === 0) return window.mySimulation.t('hint_no_clauses');
            if (results.clausesGained >= 6) return window.mySimulation.t('hint_great_progress');
            if (results.signingOutcome === 'pushed_success') return window.mySimulation.t('hint_push_success');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'decisions.stance', label: 'Stance', i18nKey: 'col_stance' },
                { key: 'decisions.focus', label: 'Focus', i18nKey: 'col_focus' },
                { key: 'decisions.concession', label: 'Concession', i18nKey: 'col_concession' },
                { key: 'results.roundValue', label: 'Round Value', i18nKey: 'col_round_value', formatter: (v) => '€' + Math.round(v).toLocaleString() },
                { key: 'results.clausesGained', label: 'Clauses', i18nKey: 'col_clauses_gained' },
                { key: 'results.trust', label: 'Trust', i18nKey: 'col_trust', formatter: (v) => v + '%' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:                `ClauseWork: Contract Negotiation`,
                    subtitle:             `Multi-Party Commercial Deal-Making Simulation`,
                    period_label:         `Round`,
                    period_of:            `of`,
                    deal_value_label:     `Deal Value`,
                    clauses_label:        `Clauses Resolved`,
                    trust_label:          `Counterparty Trust`,
                    power_label:          `Bargaining Power`,
                    decisions_heading:    `Your Negotiation Decisions`,
                    stance_label:         `Negotiation Stance`,
                    stance_aggressive:    `Aggressive`,
                    stance_balanced:      `Balanced`,
                    stance_cooperative:   `Cooperative`,
                    focus_label:          `Priority Focus Area`,
                    focus_commercial:     `Commercial Terms`,
                    focus_territorial:    `Territory and Exclusivity`,
                    focus_ip:             `IP and Liability`,
                    focus_governance:     `Governance and Disputes`,
                    concession_label:     `Concession Level (0–100)`,
                    concession_hint:      `0 = no concessions, 100 = maximum flexibility`,
                    concession_placeholder: `Enter 0 to 100`,
                    info_label:           `Information Strategy`,
                    info_reveal:          `Reveal priorities and BATNA`,
                    info_selective:       `Share selectively`,
                    info_withhold:        `Withhold key details`,
                    signing_label:        `Final Decision`,
                    signing_sign:         `Sign the Deal`,
                    signing_walk:         `Walk Away (use BATNA)`,
                    signing_continue:     `Push for Better Terms (risky)`,
                    submit_btn:           `Submit Round`,
                    undo_btn:             `Undo Last Round`,
                    concession_warning:   `Concession level must be between 0 and 100`,
                    round1_title:         `Round 1: Opening Positions and Prioritization`,
                    round1_desc:          `You represent <strong>Grupo Andino</strong>, a Colombian enterprise software company. You are negotiating a 5-year technology licensing deal with <strong>Lumina AI</strong> (Silicon Valley licensor), <strong>PacificTrade</strong> (Singapore distributor), and <strong>Crestline Ventures</strong> (London investor).<br><br>Your BATNA: Build internally for €5M over 2 years. Your goal: secure Lumina AI analytics at favorable terms to grow revenue to €15M in 3 years.<br><br><strong>This round:</strong> Present your priorities and establish your negotiation stance. The optimal focus is on territorial and exclusivity terms to secure your market position early.`,
                    round2_title:         `Round 2: Core Commercial Terms`,
                    round2_desc:          `Parties have stated their opening positions. Conflicts are emerging on royalty rates (Lumina wants 25%, you want 15%), exclusivity, and minimum commitments.<br><br><strong>This round:</strong> Negotiate the core commercial terms — royalty structure, payment terms, volume discounts, and pricing authority. Focus on commercial terms to maximize the value you capture.<br><br>Consider proposing tiered royalties (lower rate at low volume, higher at high volume) as an integrative solution that benefits both parties.`,
                    round3_title:         `Round 3: IP and Liability + Market Shock`,
                    round3_desc:          `Commercial terms are taking shape. Now negotiate the most contentious clauses: IP ownership of improvements, liability caps, indemnification, and confidentiality.<br><br>🚨 <strong>Breaking news:</strong> A major LATAM software company has launched AI analytics natively in their product. Customers now view AI-powered analytics as table stakes, not differentiation. This weakens your bargaining position.<br><br><strong>This round:</strong> Focus on IP and liability terms. Your BATNA has weakened — internal development is less attractive now that the market is commoditizing.`,
