        _updateBriefing(state) {
            var cp = (state.currentPeriod || 1);
            var over = cp > this.ROUNDS.length;
            var idx = Math.min(cp - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl && !over) {
                if (window.mySimulation && window.mySimulation.t) {
                    titleEl.innerHTML = window.mySimulation.t(round.titleKey);
                }
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl && !over) {
                if (window.mySimulation && window.mySimulation.t) {
                    briefEl.innerHTML = window.mySimulation.t(round.descriptionKey);
                }
            }

            var signingGroup = document.getElementById('signingGroup');
            if (signingGroup) {
                signingGroup.style.display = (!over && cp >= 4) ? 'block' : 'none';
            }

            if (over) {
                var b = document.getElementById('nextPeriodBtn');
                if (b) b.disabled = true;
                var u = document.getElementById('undoBtn');
                if (u) u.style.display = 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ClauseWorkAdapter(), {
            simulationType: 'clausework_negotiation',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

